import androidx.compose.ui.unit.dp
import androidx.lifecycle.ViewModelStore
import androidx.lifecycle.ViewModelStoreOwner
import androidx.lifecycle.viewmodel.compose.LocalViewModelStoreOwner
import dev.ohs.fhir.datacapture.Questionnaire
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

class MainActivity : ComponentActivity() {
  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)
    setContent { MaterialTheme { Surface(Modifier.fillMaxSize()) { AncNavigation() } } }
  }
}

private sealed interface Screen {
  data object Register : Screen
  data class Detail(val patient: Pregnancy) : Screen
  data class NewVisit(val patient: Pregnancy) : Screen
}

@Composable
private fun AncNavigation() {
  var screen by remember { mutableStateOf<Screen>(Screen.Register) }
  BackHandler(enabled = screen != Screen.Register) {
    screen = when (val s = screen) {
      is Screen.NewVisit -> Screen.Detail(s.patient)
      else -> Screen.Register
    }
  }
  when (val s = screen) {
    Screen.Register -> RegisterScreen(onOpen = { screen = Screen.Detail(it) })
    is Screen.Detail -> DetailScreen(
      patient = s.patient,
      onNewVisit = { screen = Screen.NewVisit(s.patient) },
    )
    is Screen.NewVisit -> FreshFormSession {
      NewVisitScreen(patient = s.patient, onDone = { screen = Screen.Detail(s.patient) })
    }
  }
}

@Composable
private fun RegisterScreen(onOpen: (Pregnancy) -> Unit) {
  val result by produceState<Result<List<Pregnancy>>?>(null) {
    value = withContext(Dispatchers.IO) { runCatching { Hapi.pregnancies() } }
  }
  Column(Modifier.fillMaxSize().padding(16.dp)) {
    Text("Pregnant patients", style = MaterialTheme.typography.headlineSmall)
    result?.exceptionOrNull()?.let { Text("Could not load from server: ${it.message}") }
    val list = result?.getOrNull()
    if (result == null) Text("Loading…")
    list?.let {
      LazyColumn(Modifier.weight(1f)) {
        items(it) { p ->
          Card(onClick = { onOpen(p) }, modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp)) {
            Column(Modifier.padding(12.dp)) {
              Text(p.name, style = MaterialTheme.typography.titleMedium)
              Text("Age ${p.age} · Due ${p.due} · ${p.weeks()} weeks")
            }
          }
        }
      }
    }
  }
}

@Composable
private fun DetailScreen(patient: Pregnancy, onNewVisit: () -> Unit) {
  val result by produceState<Result<List<Visit>>?>(null, patient.id) {
    value = withContext(Dispatchers.IO) { runCatching { Hapi.visits(patient.id) } }
  }
  Column(Modifier.fillMaxSize().padding(16.dp)) {
    Text(patient.name, style = MaterialTheme.typography.headlineSmall)
    Text("Age ${patient.age} · Due ${patient.due} · ${patient.weeks()} weeks")
    Button(onClick = onNewVisit, modifier = Modifier.padding(vertical = 12.dp)) { Text("Record ANC visit") }
    Text("Past visits", style = MaterialTheme.typography.titleMedium)
    result?.exceptionOrNull()?.let { Text("Could not load visits: ${it.message}") }
    if (result == null) Text("Loading…")
    result?.getOrNull()?.let { visits ->
      if (visits.isEmpty()) Text("No visits recorded yet.")
      LazyColumn(Modifier.weight(1f)) {
        items(visits) { v ->
          Card(modifier = Modifier.fillMaxWidth().padding(vertical = 4.dp)) {
            Column(Modifier.padding(12.dp)) {
              Text(v.date, style = MaterialTheme.typography.titleSmall)
              Text("Weight: ${v.weight ?: "—"}")
              Text("Blood pressure: ${v.bp?.let { "$it mmHg" } ?: "—"}")
              Text("Hemoglobin: ${v.hb ?: "—"}")
            }
          }
        }
      }
    }
  }
}

@Composable
private fun NewVisitScreen(patient: Pregnancy, onDone: () -> Unit) {
  val scope = rememberCoroutineScope()
  val questionnaire by produceState<Result<String>?>(null) {
    value = withContext(Dispatchers.IO) { runCatching { Hapi.questionnaire() } }
  }
  var error by remember { mutableStateOf<String?>(null) }
  Column(Modifier.fillMaxSize().padding(16.dp)) {
    Text("New ANC visit: ${patient.name}", style = MaterialTheme.typography.headlineSmall)
    error?.let { Text(it) }
    Box(Modifier.weight(1f)) {
      val q = questionnaire
      when {
        q == null -> Text("Loading form…")
        q.isFailure -> Text("Could not load form: ${q.exceptionOrNull()?.message}")
        else -> Questionnaire(
          questionnaireJson = q.getOrThrow(),
          onSubmit = { getResponse ->
            scope.launch {
              try {
                val response = getResponse()
                withContext(Dispatchers.IO) { Hapi.saveVisit(patient.id, response) }
                onDone()
              } catch (e: CancellationException) {
                // Validation failed; the form already shows the errors.
              } catch (e: Exception) {
                error = "Save failed: ${e.message}"
              }
            }
          },
          onCancel = onDone,
        )
      }
    }
  }
}

// Each form session gets its own ViewModelStore. Otherwise the Questionnaire's view-model
// is cached by its JSON key and the previous visit's answers reappear (kotlin-fhir-data-capture stale-form trap).
@Composable
private fun FreshFormSession(content: @Composable () -> Unit) {
  val owner = remember { object : ViewModelStoreOwner { override val viewModelStore = ViewModelStore() } }
  DisposableEffect(owner) { onDispose { owner.viewModelStore.clear() } }
  CompositionLocalProvider(LocalViewModelStoreOwner provides owner, content = content)
}

